def factorial_recursive(n):
    """Calcula o fatorial de n usando recursão."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("A entrada deve ser um inteiro não negativo.")

    # Caso base
    if n == 0:
        return 1

    # Passo recursivo
    return n * factorial_recursive(n - 1)

# Exemplo de uso:
# print(factorial_recursive(5))  # Retorna 120
# print(factorial_recursive(0))  # Retorna 1

python
def factorial_recursive(n):
    """
    Calcula o fatorial de um número inteiro não negativo n usando recursão.
    O fatorial de 0 é definido como 1.

    Gera:
        ValueError: Se n for negativo.
    """
    if n < 0:
        raise ValueError("O fatorial não está definido para números negativos.")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# Exemplo de uso:
# print(factorial_recursive(5)) # Saída: 120

