def fibonacci_recursive(n):
    """Calcula o enésimo número de Fibonacci usando recursão.
    Retorna 0 para entradas não positivas.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

